import{_ as a}from"./chunks/account-list.CVPeqkon.js";import{_ as r,c as d,o as e,ag as l}from"./chunks/framework.3IuuWm4t.js";const o="/siyuan-plugin-publisher/images/shots/platform-select.webp",i="/siyuan-plugin-publisher/images/shots/platform-config.webp",f=JSON.parse('{"title":"发布设置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1795234250000}'),s={name:"guide/settings.md"};function n(h,t,p,g,u,c){return e(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="发布设置" tabindex="-1">发布设置 <a class="header-anchor" href="#发布设置" aria-label="Permalink to &quot;发布设置&quot;">​</a></h1><p>设置左侧分五个入口：<strong>账号设置</strong>、<strong>图床设置</strong>、<strong>偏好设置</strong>、<strong>发布记录</strong>、<strong>人工智能</strong>，末尾还有<strong>关于作者</strong>。</p><p><img src="'+o+'" alt="账号设置：选择平台" loading="lazy"></p><h2 id="账号设置" tabindex="-1">账号设置 <a class="header-anchor" href="#账号设置" aria-label="Permalink to &quot;账号设置&quot;">​</a></h2><p>新增、编辑、启用或删除平台账号，并验证连通性。</p><p><img src="'+a+'" alt="账号列表" loading="lazy"></p><p>每个账号一行，可以看到：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>状态</td><td>「运行中」表示验证通过；「需授权」表示还要完成一次授权</td></tr><tr><td>平台 key</td><td>该账号的唯一标识，例如 <code>custom_Yuqueweb</code></td></tr><tr><td>管理</td><td>进入该平台的配置页</td></tr><tr><td>已启用</td><td>关掉后该平台不参与批量分发</td></tr><tr><td>删除</td><td>移除这个账号配置</td></tr></tbody></table><p>账号行左侧的手柄可以<strong>拖动排序</strong>，顺序会持久化，并同步到快速发布的卡片顺序。</p><p><img src="'+i+'" alt="平台配置表单" loading="lazy"></p><p>平台配置页里，每一行右侧的 ⓘ 可以查看该字段的说明与示例。</p><h2 id="图床设置" tabindex="-1">图床设置 <a class="header-anchor" href="#图床设置" aria-label="Permalink to &quot;图床设置&quot;">​</a></h2><p>配置图片上传方式。可选平台原生直传、内置的阿里云 OSS / 腾讯云 COS，或本机 PicGo。</p><p>从 2.4.0 起，还可在「按目录排除自动上传」中，为指定目录及其子文档或整个笔记本关闭图片自动上传。单篇文章可在发布页单独设置，并优先于目录规则生效。操作步骤与生效范围见<a href="./picbed.html#控制图片自动上传">控制图片自动上传</a>。</p><h2 id="偏好设置" tabindex="-1">偏好设置 <a class="header-anchor" href="#偏好设置" aria-label="Permalink to &quot;偏好设置&quot;">​</a></h2><p>一组影响发布行为的开关：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>去除标题编号</td><td>发布时去掉文章标题和正文各级标题开头的编号（含思源「标题块自动编号」）</td></tr><tr><td>不更新原始标题</td><td>保持思源原文标题不被平台化处理覆盖</td></tr><tr><td>去除正文 H1 / 去除挂件 HTML</td><td>按需清理正文</td></tr><tr><td>菜单显示开关</td><td>控制文档快捷菜单、快速发布、详细发布、批量分发、AI、文章管理等入口是否显示</td></tr><tr><td>忽略块引用</td><td>发布时忽略文中的块引用</td></tr><tr><td>允许修改别名</td><td>允许改文章别名（slug）；开启后需自行保证唯一，否则可能发布失败</td></tr><tr><td>发布源笔记本</td><td>限定允许发布的笔记本；<strong>留空 = 不限制</strong></td></tr></tbody></table><h3 id="关于发布源笔记本" tabindex="-1">关于发布源笔记本 <a class="header-anchor" href="#关于发布源笔记本" aria-label="Permalink to &quot;关于发布源笔记本&quot;">​</a></h3><p>用来收敛「文章管理」的列表范围，并隔离公开与非公开内容。</p><ul><li>选中后<strong>只能发布</strong>这些笔记本内的文档</li><li>文章管理的列表也会跟着过滤</li><li>发布不在范围内的文档会被拦下并给出提示</li><li>系统笔记本与用户指南笔记本会自动排除在可选范围外</li></ul><h2 id="发布记录" tabindex="-1">发布记录 <a class="header-anchor" href="#发布记录" aria-label="Permalink to &quot;发布记录&quot;">​</a></h2><p>管理当前文档在各平台上的<strong>发布记录</strong>：哪篇文档发布到了哪个平台、平台上的文章 ID 是多少。 列表只显示真正发布过的平台，每行可以「编辑」文章 ID 或「解绑」。</p><h3 id="什么时候需要它" tabindex="-1">什么时候需要它 <a class="header-anchor" href="#什么时候需要它" aria-label="Permalink to &quot;什么时候需要它&quot;">​</a></h3><ul><li>更新或删除文章时提示失败：平台上那篇文章可能已经被删除，需要先解绑再重新发布；</li><li>发布记录和平台上实际的文章 ID 对不上：直接编辑该平台的记录；</li><li>文档 ID 变了（删除重建、拆分合并、从别的工作区导入）：用列表底部的「关联已有文章」把旧记录接回来。</li></ul><h3 id="编辑与解绑" tabindex="-1">编辑与解绑 <a class="header-anchor" href="#编辑与解绑" aria-label="Permalink to &quot;编辑与解绑&quot;">​</a></h3><ol><li>打开文档（面板会自动带上当前文档，不需要手填 ID）。</li><li>进入<strong>设置 → 发布记录</strong>。</li><li>在列表里找到对应平台： <ul><li>点「编辑」可以改记录里的文章 ID，确认后立即保存；</li><li>点「解绑」并再次确认后，插件不再关联这篇文档与该平台的文章。</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">解绑不会删除平台上的文章</p><p>解绑只清理插件里的本地记录（平台 YAML 属性也会一并清空），不会调用平台接口。 文章仍然留在平台上；之后再次发布会被当作一篇新文章。</p></div><h3 id="平台上有旧文章-关联已有文章" tabindex="-1">平台上有旧文章？关联已有文章 <a class="header-anchor" href="#平台上有旧文章-关联已有文章" aria-label="Permalink to &quot;平台上有旧文章？关联已有文章&quot;">​</a></h3><p>「发布修复」的场景收在列表底部的这个入口里：文档 ID 变化后，原发布记录找不到这篇文档， 文章管理里显示「未发布」，但平台上的文章其实还在。直接重新发布会造成重复文章。</p><ol><li>打开<strong>文档 ID 已经变化</strong>的新文档；</li><li>进入<strong>设置 → 发布记录</strong>；</li><li>展开「平台上有旧文章？关联已有文章」；</li><li>选择平台，填入<strong>平台上实际存在的文章 ID</strong>，点「关联」。</li></ol><p>记录重新对上之后，再次发布就是对平台上的旧文章做更新。</p><h3 id="怎么拿到平台上的文章-id" tabindex="-1">怎么拿到平台上的文章 ID <a class="header-anchor" href="#怎么拿到平台上的文章-id" aria-label="Permalink to &quot;怎么拿到平台上的文章 ID&quot;">​</a></h3><table tabindex="0"><thead><tr><th>平台类型</th><th>从哪里拿</th></tr></thead><tbody><tr><td>多数博客平台</td><td>打开文章，看地址栏里的数字或 slug</td></tr><tr><td>GitHub / GitLab 系</td><td>记录里的 <code>postid</code> 对应文章在仓库中的路径或 slug</td></tr><tr><td>网页授权平台</td><td>打开文章编辑页，地址栏里通常带有文章 ID</td></tr></tbody></table><h3 id="与「强制删除」的区别" tabindex="-1">与「强制删除」的区别 <a class="header-anchor" href="#与「强制删除」的区别" aria-label="Permalink to &quot;与「强制删除」的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>做什么</th></tr></thead><tbody><tr><td><strong>发布记录 → 编辑</strong></td><td>改记录里的文章 ID（记录本来就在）</td></tr><tr><td><strong>发布记录 → 解绑</strong></td><td>丢弃该文档在该平台的发布记录，之后重新发布</td></tr><tr><td><strong>发布记录 → 关联已有文章</strong></td><td>保留旧记录，把它接回新文档</td></tr><tr><td><strong>强制删除</strong>（发布页）</td><td>与「解绑」效果相同，只是入口在发布页/快速发布卡片</td></tr></tbody></table><p>需要重新发布时用解绑（或强制删除）；只是想恢复关联时用「关联已有文章」。</p><h2 id="人工智能" tabindex="-1">人工智能 <a class="header-anchor" href="#人工智能" aria-label="Permalink to &quot;人工智能&quot;">​</a></h2><p>配置 AI 服务，用于自动生成标题、摘要、标签与分类。详见 <a href="./ai.html">AI 辅助</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>平台字段不清楚：看<a href="/siyuan-plugin-publisher/platforms/">平台支持</a>里对应平台的那一篇</li><li>遇到问题：<a href="./faq.html">常见问题</a></li></ul>',40)])])}const _=r(s,[["render",n]]);export{f as __pageData,_ as default};
